// Union européenne : construction, élargissements, institutions, droit, budget,
// politiques, droits fondamentaux. Thème le moins réussi en 2026 (50 %).
BANK.push(
// --- Construction européenne ---
{id:"ue-01",t:"ue",q:"Quelle déclaration du 9 mai 1950 propose de mettre en commun la production de charbon et d'acier ?",o:["La déclaration Schuman","Le discours de Zurich de Churchill","Le plan Marshall","La déclaration de Messine"],a:0,e:"Robert Schuman, inspiré par Jean Monnet. Le 9 mai est la Journée de l'Europe.",x:"Robert Schuman était alors ministre français des Affaires étrangères. Il proposait de placer la production franco-allemande de charbon et d'acier sous une Haute Autorité commune.",u:["https://www.vie-publique.fr/questions-reponses/274269-ue-4-questions-sur-la-journee-de-leurope-du-9-mai","https://fr.wikipedia.org/wiki/D%C3%A9claration_du_9_mai_1950"],s:"Fiche 5"},
{id:"ue-02",t:"ue",q:"Quel traité a créé la Communauté européenne du charbon et de l'acier (CECA) ?",o:["Le traité de Rome (1957)","Le traité de Paris (1951)","Le traité de Maastricht (1992)","Le traité de Bruxelles (1948)"],a:1,e:"Traité de Paris, signé le 18 avril 1951 par six États.",x:"Conclu pour 50 ans, le traité CECA a expiré le 23 juillet 2002. Jean Monnet a été le premier président de la Haute Autorité.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_instituant_la_Communaut%C3%A9_europ%C3%A9enne_du_charbon_et_de_l'acier","https://fr.wikipedia.org/wiki/Communaut%C3%A9_europ%C3%A9enne_du_charbon_et_de_l'acier"],s:"Fiche 5"},
{id:"ue-03",t:"ue",q:"Lequel de ces pays ne faisait pas partie des six fondateurs de la CECA ?",o:["Belgique","Luxembourg","Royaume-Uni","Italie"],a:2,e:"France, RFA, Italie, Belgique, Pays-Bas, Luxembourg. Le Royaume-Uni adhère en 1973.",x:"Le Royaume-Uni avait refusé de participer à la CECA ; sa candidature aux Communautés a ensuite été bloquée deux fois par le général de Gaulle (1963 et 1967).",u:["https://www.vie-publique.fr/fiches/20310-comment-sest-construite-lunion-europeenne","https://fr.wikipedia.org/wiki/Communaut%C3%A9_europ%C3%A9enne_du_charbon_et_de_l'acier"],s:"Fiche 5"},
{id:"ue-04",t:"ue",q:"Quelles communautés les traités de Rome du 25 mars 1957 ont-ils créées ?",o:["La CECA et la CED","La CEE et Euratom","L'UE et l'UEM","L'AELE et la CEE"],a:1,e:"Communauté économique européenne (marché commun) et Communauté européenne de l'énergie atomique.",x:"Signés au Capitole le 25 mars 1957, ils sont entrés en vigueur le 1er janvier 1958. Le traité CEE est devenu le TFUE avec le traité de Lisbonne.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_instituant_la_Communaut%C3%A9_%C3%A9conomique_europ%C3%A9enne","https://fr.wikipedia.org/wiki/Trait%C3%A9_instituant_la_Communaut%C3%A9_europ%C3%A9enne_de_l'%C3%A9nergie_atomique"],s:"Fiche 5"},
{id:"ue-05",t:"ue",q:"Quel traité de 1986 a fixé l'achèvement du marché intérieur au 1er janvier 1993 ?",o:["Le traité de Nice","L'Acte unique européen","Le traité d'Amsterdam","Le traité de Lisbonne"],a:1,e:"Signé en 1986, entré en vigueur le 1er juillet 1987.",x:"Signé en février 1986, sous la présidence de la Commission de Jacques Delors, il étend le vote à la majorité qualifiée au Conseil et renforce le rôle du Parlement européen.",u:["https://fr.wikipedia.org/wiki/Acte_unique_europ%C3%A9en"],s:"Fiche 5"},
{id:"ue-06",t:"ue",q:"Quel traité a créé l'Union européenne et la citoyenneté européenne ?",o:["Le traité de Rome","Le traité de Maastricht","Le traité d'Amsterdam","Le traité de Lisbonne"],a:1,e:"Maastricht (1992) : UE, citoyenneté, union économique et monétaire, critères de convergence.",x:"La citoyenneté européenne s'ajoute à la citoyenneté nationale sans la remplacer : elle donne notamment le droit de vote aux élections municipales et européennes dans l'État de résidence.",u:["https://www.vie-publique.fr/fiches/20320-qui-est-citoyen-europeen","https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Maastricht"],s:"Fiche 5"},
{id:"ue-07",t:"ue",q:"Quels traités ont préparé l'élargissement de 2004 vers l'Europe centrale ?",o:["Rome et Paris","Amsterdam (1997) et Nice (2001)","Maastricht et Lisbonne","L'Acte unique et Schengen"],a:1,e:"Ils adaptent les institutions à une Union élargie.",x:"Le traité d'Amsterdam (1997) intègre l'acquis de Schengen dans le cadre de l'Union ; le traité de Nice (2001) repondère les voix au Conseil et plafonne la taille des institutions.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_d'Amsterdam","https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Nice"],s:"Fiche 5"},
{id:"ue-08",t:"ue",q:"Quels pays ont rejeté par référendum le traité établissant une Constitution pour l'Europe en 2005 ?",o:["La France et les Pays-Bas","La France et l'Irlande","Le Danemark et la Suède","Le Royaume-Uni et la Pologne"],a:0,e:"France le 29 mai 2005, Pays-Bas le 1er juin 2005.",x:"En France, le « non » l'a emporté avec 54,7 % des voix. Le contenu a ensuite été largement repris par le traité de Lisbonne.",u:["https://www.vie-publique.fr/fiches/20313-existe-t-il-une-constitution-europeenne","https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_fran%C3%A7ais_sur_le_trait%C3%A9_%C3%A9tablissant_une_Constitution_pour_l'Europe"],s:"Fiche 5"},
{id:"ue-09",t:"ue",q:"Quand le traité de Lisbonne est-il entré en vigueur ?",o:["13 décembre 2007","1er janvier 2008","1er décembre 2009","1er novembre 2014"],a:2,e:"Signé le 13 décembre 2007.",x:"Son entrée en vigueur a été retardée par le « non » irlandais de juin 2008 ; un second référendum irlandais l'a approuvé en octobre 2009. En France, il a été ratifié par voie parlementaire en février 2008.",u:["https://www.vie-publique.fr/fiches/20316-comment-le-traite-de-lisbonne-t-il-ete-ratifie","https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"Fiche 5"},
{id:"ue-10",t:"ue",q:"Lequel de ces apports n'est pas dû au traité de Lisbonne ?",o:["La présidence stable du Conseil européen","La clause de retrait (art. 50 TUE)","L'initiative citoyenne européenne","La création de l'euro"],a:3,e:"L'UEM vient de Maastricht ; l'euro existe depuis 1999.",x:"Le traité de Lisbonne a aussi donné la personnalité juridique à l'Union, fait du haut représentant pour les affaires étrangères un vice-président de la Commission et rendu la Charte des droits fondamentaux contraignante.",u:["https://www.vie-publique.fr/fiches/20315-quest-ce-que-le-traite-de-lisbonne","https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"Fiche 5"},
{id:"ue-11",t:"ue",q:"Quels traités fondent aujourd'hui l'Union européenne ?",o:["Le traité sur l'Union européenne (TUE) et le traité sur le fonctionnement de l'UE (TFUE)","Le traité de Rome et le traité de Paris","La Constitution européenne","Le traité de Maastricht seul"],a:0,e:"Tels que modifiés par Lisbonne ; la Charte des droits fondamentaux a la même valeur.",x:"Le TUE pose les principes, les valeurs et les institutions ; le TFUE détaille les compétences et le fonctionnement. Les deux traités ont la même valeur juridique.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_sur_l'Union_europ%C3%A9enne","https://fr.wikipedia.org/wiki/Trait%C3%A9_sur_le_fonctionnement_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-12",t:"ue",q:"En quelle année le Royaume-Uni, l'Irlande et le Danemark ont-ils rejoint les Communautés ?",o:["1957","1973","1981","1995"],a:1,e:"Premier élargissement, le 1er janvier 1973.",x:"La Norvège, qui avait aussi signé le traité d'adhésion, l'a rejeté par référendum en 1972. Le Royaume-Uni est sorti de l'Union le 31 janvier 2020.",u:["https://www.vie-publique.fr/fiches/20364-quest-ce-que-lelargissement-de-lunion-europeenne","https://fr.wikipedia.org/wiki/%C3%89largissement_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-13",t:"ue",q:"Quel pays a adhéré seul en 1981 ?",o:["L'Espagne","Le Portugal","La Grèce","L'Autriche"],a:2,e:"Espagne et Portugal en 1986.",x:"Comme l'Espagne et le Portugal en 1986, la Grèce adhère quelques années après la chute de sa dictature (régime des colonels, 1967-1974).",u:["https://www.vie-publique.fr/fiches/20364-quest-ce-que-lelargissement-de-lunion-europeenne","https://fr.wikipedia.org/wiki/%C3%89largissement_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-14",t:"ue",q:"Quels pays ont adhéré en 1995 ?",o:["Autriche, Finlande, Suède","Espagne, Portugal, Grèce","Bulgarie, Roumanie, Croatie","Norvège, Suisse, Islande"],a:0,e:"La Norvège a refusé l'adhésion par référendum (1972 et 1994).",x:"Ces trois pays étaient auparavant membres de l'Association européenne de libre-échange (AELE). La Norvège est restée dans l'Espace économique européen.",u:["https://fr.wikipedia.org/wiki/Quatri%C3%A8me_%C3%A9largissement_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-15",t:"ue",q:"Combien de pays ont adhéré lors de l'élargissement du 1er mai 2004 ?",o:["2","5","10","12"],a:2,e:"Dix pays d'Europe centrale et méditerranéenne (dont Pologne, Chypre, Malte, pays baltes).",x:"Les dix pays : Chypre, Estonie, Hongrie, Lettonie, Lituanie, Malte, Pologne, République tchèque, Slovaquie et Slovénie. C'est le plus important élargissement de l'histoire de l'Union.",u:["https://fr.wikipedia.org/wiki/Cinqui%C3%A8me_%C3%A9largissement_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-16",t:"ue",q:"Quels pays ont adhéré en 2007 ?",o:["Bulgarie et Roumanie","Croatie et Slovénie","Malte et Chypre","Estonie et Lettonie"],a:0,e:"Puis la Croatie en 2013.",x:"La Bulgarie et la Roumanie ont rejoint pleinement l'espace Schengen le 1er janvier 2025 ; la Bulgarie est entrée dans la zone euro en 2026.",u:["https://fr.wikipedia.org/wiki/Cinqui%C3%A8me_%C3%A9largissement_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-17",t:"ue",q:"Quand le Royaume-Uni est-il sorti de l'Union européenne ?",o:["23 juin 2016","29 mars 2019","31 janvier 2020","1er janvier 2021"],a:2,e:"Le référendum date du 23 juin 2016 ; la période de transition a pris fin le 31 décembre 2020.",x:"Au référendum du 23 juin 2016, le « Leave » a obtenu 51,9 % des voix. Le Royaume-Uni est le seul État à avoir quitté l'Union, sur le fondement de l'article 50 TUE.",u:["https://www.vie-publique.fr/eclairage/272932-brexit-retrait-effectif-du-royaume-uni-de-lue-le-31-janvier-2020","https://fr.wikipedia.org/wiki/Brexit"],s:"Fiche 5"},
{id:"ue-18",t:"ue",q:"Combien l'Union européenne compte-t-elle d'États membres ?",o:["25","27","28","30"],a:1,e:"27 depuis le Brexit.",x:"En 2025, les pays candidats officiels étaient l'Albanie, la Bosnie-Herzégovine, la Géorgie, la Macédoine du Nord, la Moldavie, le Monténégro, la Serbie, la Turquie et l'Ukraine.",u:["https://european-union.europa.eu/principles-countries-history/eu-countries_fr","https://fr.wikipedia.org/wiki/%C3%89tats_membres_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-19",t:"ue",q:"Quel article du TUE organise le retrait d'un État membre ?",o:["Article 2","Article 7","Article 49","Article 50"],a:3,e:"Art. 50, utilisé pour le Brexit ; l'art. 49 régit l'adhésion.",x:"L'État notifie son intention au Conseil européen ; les traités cessent de s'appliquer à la date d'entrée en vigueur de l'accord de retrait ou, à défaut, deux ans après la notification, sauf prorogation. Le Royaume-Uni l'a notifié le 29 mars 2017.",u:["https://www.vie-publique.fr/fiches/20367-quest-ce-quun-retrait-volontaire-de-lunion-europeenne-article-50-tue","https://fr.wikipedia.org/wiki/Article_50_du_trait%C3%A9_sur_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-20",t:"ue",q:"Comment le Conseil décide-t-il de l'adhésion d'un nouvel État ?",o:["À la majorité qualifiée","À l'unanimité, après approbation du Parlement européen","À la majorité simple","Par référendum européen"],a:1,e:"Art. 49 TUE, puis ratification par tous les États membres.",x:"Le Parlement européen se prononce à la majorité des membres qui le composent. Le traité d'adhésion est ensuite ratifié par tous les États ; en France, par référendum ou par le Congrès à la majorité des 3/5 (art. 88-5).",u:["https://www.vie-publique.fr/fiches/20366-quelles-sont-les-conditions-et-les-modalites-dadhesion-lue","https://fr.wikipedia.org/wiki/Crit%C3%A8res_de_Copenhague"],s:"Fiche 5"},
{id:"ue-21",t:"ue",q:"En quelle année ont été définis les critères de Copenhague ?",o:["1957","1986","1993","2004"],a:2,e:"Conseil européen de Copenhague, juin 1993.",x:"Les critères sont politiques (démocratie, État de droit, droits de l'homme, minorités), économiques (économie de marché viable) et juridiques (reprise de l'acquis communautaire).",u:["https://fr.wikipedia.org/wiki/Crit%C3%A8res_de_Copenhague"],s:"Fiche 5"},
// --- Euro et zone euro ---
{id:"ue-22",t:"ue",q:"Depuis quand les pièces et billets en euros circulent-ils ?",o:["1er janvier 1999","1er janvier 2002","1er janvier 1993","1er janvier 2008"],a:1,e:"L'euro existe sous forme scripturale depuis 1999.",x:"Le 1er janvier 1999, les parités ont été irrévocablement fixées : 1 € = 6,55957 francs. Les pièces et billets en francs ont cessé d'avoir cours légal le 17 février 2002.",u:["https://www.vie-publique.fr/fiches/21793-quest-ce-que-leuro","https://fr.wikipedia.org/wiki/Euro"],s:"Fiche 5"},
{id:"ue-23",t:"ue",q:"Quel pays a rejoint la zone euro le 1er janvier 2026 ?",o:["La Croatie","La Bulgarie","La Roumanie","La Pologne"],a:1,e:"21e membre ; la Croatie était entrée le 1er janvier 2023.",x:"Le taux de conversion a été fixé à 1,95583 lev pour 1 euro, la parité que le lev entretenait déjà avec l'euro.",u:["https://european-union.europa.eu/institutions-law-budget/euro/countries-using-euro_fr","https://fr.wikipedia.org/wiki/Zone_euro"],s:"Fiche 5",act:1},
{id:"ue-24",t:"ue",q:"Lequel de ces États membres n'utilise pas l'euro ?",o:["L'Irlande","La Finlande","La Suède","La Slovaquie"],a:2,e:"Hors zone euro : le Danemark (clause d'exemption) et cinq États « à dérogation », tenus d'adopter l'euro à terme : Suède, Pologne, Tchéquie, Hongrie, Roumanie.",x:"La Suède a rejeté l'euro par référendum en 2003 et ne participe pas au MCE II, ce qui l'empêche de remplir les critères. Le Danemark a obtenu sa clause d'exemption après le rejet du traité de Maastricht en 1992.",u:["https://european-union.europa.eu/institutions-law-budget/euro/countries-using-euro_fr","https://fr.wikipedia.org/wiki/Zone_euro"],s:"Fiche 5"},
{id:"ue-25",t:"ue",q:"Où siège la Banque centrale européenne ?",o:["Bruxelles","Luxembourg","Francfort","Strasbourg"],a:2,e:"Francfort-sur-le-Main.",x:"La BCE a été créée le 1er juin 1998. Avec les banques centrales nationales de la zone euro, elle forme l'Eurosystème.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-central-bank-ecb_fr","https://fr.wikipedia.org/wiki/Banque_centrale_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-26",t:"ue",q:"Quel est l'objectif d'inflation de la BCE à moyen terme ?",o:["0 %","1 %","2 %","3 %"],a:2,e:"Stabilité des prix : 2 % à moyen terme (objectif symétrique depuis 2021).",x:"L'inflation est mesurée par l'indice des prix à la consommation harmonisé (IPCH). L'objectif est symétrique : un écart à la baisse est aussi indésirable qu'un écart à la hausse.",u:["https://www.ecb.europa.eu/mopo/strategy/html/index.fr.html"],s:"Fiche 5"},
{id:"ue-27",t:"ue",q:"Qui préside la Banque centrale européenne en 2026 ?",o:["Mario Draghi","Christine Lagarde","Jean-Claude Trichet","François Villeroy de Galhau"],a:1,e:"Depuis novembre 2019, mandat de 8 ans non renouvelable (jusqu'en octobre 2027).",x:"Elle avait auparavant dirigé le Fonds monétaire international (2011-2019) et été ministre de l'Économie (2007-2011).",u:["https://fr.wikipedia.org/wiki/Christine_Lagarde"],s:"Fiche 5",act:1},
{id:"ue-28",t:"ue",q:"La politique monétaire de la zone euro est une compétence :",o:["Exclusive de l'Union","Partagée","D'appui","Nationale"],a:0,e:"Art. 3 TFUE, comme l'union douanière et la politique commerciale commune.",x:"Dans les domaines de compétence exclusive, seule l'Union peut légiférer, sauf habilitation des États. Les autres catégories sont les compétences partagées (art. 4 TFUE) et d'appui (art. 6 TFUE).",u:["https://www.vie-publique.fr/fiches/21794-comment-fonctionne-la-zone-euro-et-role-de-la-banque-centrale-europeenne"],s:"Fiche 5"},
// --- Institutions ---
{id:"ue-29",t:"ue",q:"Combien de députés compte le Parlement européen depuis les élections de juin 2024 ?",o:["705","720","751","783"],a:1,e:"720 députés élus pour 5 ans, dont 81 pour la France.",x:"Le nombre de sièges est plafonné à 750 plus le président (art. 14 TUE), avec au moins 6 et au plus 96 sièges par État. L'Allemagne en a 96 ; Malte, Chypre et le Luxembourg, 6.",u:["https://www.vie-publique.fr/fiches/20339-combien-y-t-il-de-deputes-au-parlement-europeen","https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"Fiche 5"},
{id:"ue-30",t:"ue",q:"Combien de députés européens sont élus en France ?",o:["72","74","79","81"],a:3,e:"81 sièges depuis 2024.",x:"Depuis 2019, les eurodéputés français sont élus dans une circonscription nationale unique, à la proportionnelle, avec un seuil de 5 % des suffrages exprimés.",u:["https://www.vie-publique.fr/fiches/20338-comment-les-deputes-europeens-sont-ils-elus","https://fr.wikipedia.org/wiki/%C3%89lections_europ%C3%A9ennes_de_2024_en_France"],s:"Fiche 5"},
{id:"ue-31",t:"ue",q:"Depuis quand le Parlement européen est-il élu au suffrage universel direct ?",o:["1957","1979","1992","2009"],a:1,e:"Simone Veil est la première présidente du Parlement élu (1979).",x:"Ce mode d'élection a été décidé en 1976 ; auparavant, les députés européens étaient désignés par les parlements nationaux.",u:["https://www.vie-publique.fr/eclairage/19531-elections-europeennes-resultats-des-scrutins-depuis-1979","https://fr.wikipedia.org/wiki/%C3%89lections_europ%C3%A9ennes_de_1979"],s:"Connaissance UE"},
{id:"ue-32",t:"ue",q:"Où le Parlement européen a-t-il son siège officiel ?",o:["Bruxelles","Strasbourg","Luxembourg","Francfort"],a:1,e:"Sessions plénières à Strasbourg ; commissions à Bruxelles ; secrétariat à Luxembourg.",x:"Les sièges sont fixés par un protocole annexé aux traités : douze sessions plénières mensuelles par an à Strasbourg. Le Parlement est la seule institution de l'Union élue au suffrage universel direct.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-parliament_fr","https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"Fiche 5"},
{id:"ue-33",t:"ue",q:"Qui élit le président de la Commission européenne ?",o:["Le Conseil européen seul","Le Parlement européen, sur proposition du Conseil européen","Les citoyens au suffrage direct","Le Conseil de l'UE"],a:1,e:"Le Conseil européen propose en tenant compte des élections ; le Parlement élit à la majorité de ses membres.",x:"Le Conseil européen statue à la majorité qualifiée. Le collège des commissaires est ensuite approuvé en bloc par le Parlement, après audition de chaque candidat.",u:["https://www.vie-publique.fr/fiches/20331-comment-sont-nommes-les-membres-de-la-commission-europeenne","https://fr.wikipedia.org/wiki/Pr%C3%A9sident_de_la_Commission_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-34",t:"ue",q:"Quelle institution peut renverser la Commission européenne par une motion de censure ?",o:["Le Conseil européen","Le Parlement européen","La Cour de justice","Le Conseil de l'UE"],a:1,e:"Motion adoptée à la majorité des deux tiers des suffrages exprimés et à la majorité des membres.",x:"La Commission Santer a démissionné en 1999 sous la menace d'une motion de censure.",u:["https://www.vie-publique.fr/fiches/20345-de-quels-moyens-de-controle-le-parlement-europeen-dispose-t-il"],s:"Connaissance UE"},
{id:"ue-35",t:"ue",q:"Qui compose le Conseil européen ?",o:["Les ministres de chaque État selon le sujet","Les chefs d'État ou de gouvernement, son président et le président de la Commission","Les 720 députés européens","Les gouverneurs des banques centrales"],a:1,e:"Il fixe les grandes orientations et ne légifère pas.",x:"Le haut représentant pour les affaires étrangères participe à ses travaux. Le Conseil européen est devenu une institution à part entière avec le traité de Lisbonne.",u:["https://www.vie-publique.fr/fiches/20336-quest-ce-que-le-conseil-europeen","https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-council_fr"],s:"Fiche 5"},
{id:"ue-36",t:"ue",q:"Qui préside le Conseil européen depuis décembre 2024 ?",o:["Charles Michel","António Costa","Donald Tusk","Herman Van Rompuy"],a:1,e:"Mandat de deux ans et demi, renouvelable une fois : le premier court du 1er décembre 2024 au 31 mai 2027.",x:"Ancien Premier ministre du Portugal (2015-2024), il a succédé au Belge Charles Michel.",u:["https://fr.wikipedia.org/wiki/Ant%C3%B3nio_Costa"],s:"Fiche 5",act:1},
{id:"ue-37",t:"ue",q:"Quelle est la durée du mandat du président du Conseil européen ?",o:["6 mois","2 ans et demi, renouvelable une fois","5 ans","Illimitée"],a:1,e:"Poste stable créé par le traité de Lisbonne (premier titulaire : Herman Van Rompuy).",x:"Titulaires : Herman Van Rompuy (2009-2014), Donald Tusk (2014-2019), Charles Michel (2019-2024), António Costa (depuis décembre 2024). Il est élu par le Conseil européen à la majorité qualifiée.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sident_du_Conseil_europ%C3%A9en"],s:"Fiche 5"},
{id:"ue-38",t:"ue",q:"Qui siège au Conseil de l'Union européenne ?",o:["Un ministre par État membre, selon le sujet traité","Les chefs d'État ou de gouvernement","Les commissaires européens","Les juges de la CJUE"],a:0,e:"Il est co-législateur et co-autorité budgétaire avec le Parlement.",x:"Ses travaux sont préparés par le Comité des représentants permanents (Coreper). Il siège à Bruxelles, et à Luxembourg en avril, juin et octobre.",u:["https://www.vie-publique.fr/fiches/20328-quest-ce-que-le-conseil-de-lunion-europeenne-ue","https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/council-european-union_fr"],s:"Fiche 5"},
{id:"ue-39",t:"ue",q:"Quelle est la durée de la présidence tournante du Conseil de l'UE ?",o:["3 mois","6 mois","1 an","2 ans et demi"],a:1,e:"Chaque État la préside six mois, par trios.",x:"La présidence organise et préside les réunions du Conseil, sauf le Conseil des affaires étrangères, présidé par le haut représentant. La France l'a exercée pour la dernière fois au premier semestre 2022.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-40",t:"ue",q:"Quel État membre préside le Conseil de l'UE au second semestre 2026 ?",o:["Chypre","L'Irlande","La Lituanie","La Grèce"],a:1,e:"Chypre au 1er semestre 2026, Irlande jusqu'au 31 décembre 2026, puis Lituanie (1er semestre 2027) et Grèce (2nd semestre 2027).",x:"L'Irlande, la Lituanie et la Grèce forment le trio de présidences de juillet 2026 à décembre 2027.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l'Union_europ%C3%A9enne"],s:"Fiche 5 et 8",act:1},
{id:"ue-41",t:"ue",q:"Quel État membre présidera le Conseil de l'UE au premier semestre 2027 ?",o:["L'Irlande","La Lituanie","La Grèce","La Pologne"],a:1,e:"Lituanie de janvier à juin 2027, puis Grèce de juillet à décembre 2027.",x:"C'est la deuxième présidence lituanienne, après celle du second semestre 2013.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l'Union_europ%C3%A9enne"],s:"Fiche 8",act:1},
{id:"ue-42",t:"ue",q:"Combien de commissaires compte la Commission européenne ?",o:["15","20","27","45"],a:2,e:"Un par État membre, président et haut représentant compris.",x:"Les commissaires sont indépendants des gouvernements nationaux. Le traité de Lisbonne prévoyait de réduire le collège, mais le Conseil européen a décidé de maintenir un commissaire par État.",u:["https://www.vie-publique.fr/fiches/20330-quest-ce-que-la-commission-europeenne","https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-commission_fr"],s:"Fiche 5"},
{id:"ue-43",t:"ue",q:"Qui préside la Commission européenne en 2026 ?",o:["Jean-Claude Juncker","Ursula von der Leyen","Roberta Metsola","Kaja Kallas"],a:1,e:"Second mandat depuis le 1er décembre 2024.",x:"Ancienne ministre allemande de la Défense, elle préside la Commission depuis décembre 2019 ; elle est la première femme à ce poste.",u:["https://fr.wikipedia.org/wiki/Ursula_von_der_Leyen"],s:"Fiche 5",act:1},
{id:"ue-44",t:"ue",q:"Qui est haut représentant de l'Union pour les affaires étrangères et la politique de sécurité depuis décembre 2024 ?",o:["Josep Borrell","Kaja Kallas","Federica Mogherini","Thierry Breton"],a:1,e:"L'ancienne Première ministre estonienne, également vice-présidente de la Commission.",x:"Le haut représentant préside le Conseil des affaires étrangères et dirige le Service européen pour l'action extérieure (SEAE).",u:["https://www.vie-publique.fr/fiches/20396-quel-est-le-role-du-haut-representant-ue-pour-les-affaires-etrangeres","https://fr.wikipedia.org/wiki/Kaja_Kallas"],s:"Connaissance UE",act:1},
{id:"ue-45",t:"ue",q:"Combien d'institutions l'article 13 du TUE énumère-t-il ?",o:["5","7","9","12"],a:1,e:"Parlement, Conseil européen, Conseil, Commission, CJUE, BCE, Cour des comptes.",x:"Le Conseil européen et la BCE sont devenus des institutions avec le traité de Lisbonne (2009).",u:["https://fr.wikipedia.org/wiki/Institutions_de_l'Union_europ%C3%A9enne"],s:"TUE, art. 13"},
{id:"ue-46",t:"ue",q:"Lequel de ces organes est une institution de l'Union européenne ?",o:["La Banque européenne d'investissement","Le Comité des régions","La Cour des comptes européenne","Le Médiateur européen"],a:2,e:"BEI, Comité des régions et Médiateur sont des organes, pas des institutions.",x:"Instituée par un traité de 1975, la Cour des comptes européenne est devenue une institution avec le traité de Maastricht.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-court-auditors-eca_fr","https://fr.wikipedia.org/wiki/Cour_des_comptes_europ%C3%A9enne"],s:"TUE, art. 13"},
{id:"ue-47",t:"ue",q:"Où siège la Cour des comptes européenne ?",o:["Bruxelles","Luxembourg","Strasbourg","Francfort"],a:1,e:"Un membre par État ; elle contrôle les finances de l'Union.",x:"Elle n'a pas de pouvoir juridictionnel : elle signale les irrégularités à l'OLAF ou au Parquet européen.",u:["https://www.vie-publique.fr/fiches/20350-quel-est-le-role-de-la-cour-des-comptes-europeenne","https://fr.wikipedia.org/wiki/Cour_des_comptes_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-48",t:"ue",q:"Qu'est-ce que le renvoi préjudiciel devant la CJUE ?",o:["Un recours de la Commission contre un État","La question posée par un juge national sur l'interprétation ou la validité du droit de l'Union","Un appel contre un arrêt du Tribunal","Une plainte d'un citoyen contre un autre citoyen"],a:1,e:"Il garantit l'interprétation uniforme du droit de l'Union.",x:"Prévu à l'article 267 TFUE, il est en principe obligatoire pour les juridictions statuant en dernier ressort. L'arrêt rendu s'impose au juge national qui a posé la question.",u:["https://www.vie-publique.fr/fiches/20349-quels-sont-les-recours-possibles-aupres-de-la-cjue","https://fr.wikipedia.org/wiki/Renvoi_pr%C3%A9judiciel_devant_la_Cour_de_justice_de_l%E2%80%99Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-49",t:"ue",q:"Quel recours la Commission peut-elle engager contre un État qui ne respecte pas le droit de l'Union ?",o:["Le recours en annulation","Le recours en manquement","Le renvoi préjudiciel","La QPC"],a:1,e:"Elle saisit la CJUE après une procédure précontentieuse.",x:"Si l'État ne se conforme pas au premier arrêt, la Cour peut lui infliger une somme forfaitaire et/ou une astreinte (art. 260 TFUE).",u:["https://fr.wikipedia.org/wiki/Recours_en_manquement","https://www.vie-publique.fr/fiches/20349-quels-sont-les-recours-possibles-aupres-de-la-cjue"],s:"Fiche 5"},
{id:"ue-50",t:"ue",q:"Quels sont les deux arrêts de la Cour de justice qui posent l'effet direct (1963) et la primauté (1964) du droit communautaire ?",o:["Van Gend en Loos et Costa c/ ENEL","Cassis de Dijon et Francovich","Nicolo et Sarran","Bosman et Factortame"],a:0,e:"Van Gend en Loos (1963) : effet direct. Costa c/ ENEL (1964) : primauté.",x:"En France, le Conseil d'État n'a accepté de faire prévaloir un traité sur une loi postérieure qu'en 1989 (arrêt Nicolo).",u:["https://fr.wikipedia.org/wiki/Arr%C3%AAt_van_Gend_en_Loos","https://fr.wikipedia.org/wiki/Arr%C3%AAt_Costa_contre_ENEL"],s:"Connaissance UE"},
{id:"ue-51",t:"ue",q:"Où siège la Cour européenne des droits de l'homme ?",o:["Luxembourg","Strasbourg","La Haye","Genève"],a:1,e:"Elle relève du Conseil de l'Europe et applique la CEDH.",x:"Depuis 1998, la Cour est permanente et peut être saisie directement par toute personne, après épuisement des voies de recours internes.",u:["https://www.vie-publique.fr/fiches/38293-quel-est-le-role-de-la-cour-europeenne-des-droits-de-lhomme","https://fr.wikipedia.org/wiki/Cour_europ%C3%A9enne_des_droits_de_l'homme"],s:"Fiche 5"},
{id:"ue-52",t:"ue",q:"Combien d'États membres compte le Conseil de l'Europe ?",o:["27","46","47","57"],a:1,e:"46 depuis l'exclusion de la Russie en mars 2022.",x:"Créé par le traité de Londres du 5 mai 1949, il siège à Strasbourg. Tous les États de l'Union européenne en sont membres.",u:["https://www.vie-publique.fr/fiches/20299-quest-ce-que-le-conseil-de-leurope","https://fr.wikipedia.org/wiki/Conseil_de_l'Europe"],s:"Fiche 5"},
{id:"ue-53",t:"ue",q:"En quelle année a été signée la Convention européenne de sauvegarde des droits de l'homme ?",o:["1948","1950","1957","2000"],a:1,e:"Signée à Rome le 4 novembre 1950, ratifiée par la France en 1974.",x:"La France l'a ratifiée en 1974 et n'a accepté le droit de recours individuel qu'en 1981.",u:["https://www.vie-publique.fr/questions-reponses/293946-france-cedh-50e-anniversaire-de-la-ratification-de-la-convention","https://fr.wikipedia.org/wiki/Convention_europ%C3%A9enne_des_droits_de_l'homme"],s:"Fiche 5"},
{id:"ue-54",t:"ue",q:"Le Conseil de l'Europe est :",o:["Une institution de l'UE","Une organisation internationale distincte de l'UE","Le nom officiel du Conseil européen","Une agence de l'ONU"],a:1,e:"Ne pas confondre Conseil européen (chefs d'État), Conseil de l'UE (ministres) et Conseil de l'Europe.",x:"Il promeut les droits de l'homme, la démocratie et l'État de droit. Son drapeau aux douze étoiles (1955) a ensuite été adopté par les Communautés européennes.",u:["https://www.vie-publique.fr/fiches/20299-quest-ce-que-le-conseil-de-leurope","https://fr.wikipedia.org/wiki/Conseil_de_l'Europe"],s:"Fiche 5"},
// --- Droit et décision ---
{id:"ue-55",t:"ue",q:"Dans la procédure législative ordinaire, qui adopte les actes ?",o:["La Commission seule","Le Parlement européen et le Conseil de l'UE","Le Conseil européen","La CJUE"],a:1,e:"La Commission propose ; Parlement et Conseil codécident.",x:"Héritière de la « codécision » créée par le traité de Maastricht, elle est devenue la procédure de droit commun avec Lisbonne. Les compromis sont souvent négociés en « trilogues » entre Parlement, Conseil et Commission.",u:["https://www.vie-publique.fr/fiches/20346-comment-sont-prises-les-decisions-au-sein-de-lunion-europeenne","https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"Fiche 5"},
{id:"ue-56",t:"ue",q:"Quel acte de l'Union vise des destinataires désignés et est obligatoire pour eux ?",o:["Le règlement","La directive","La décision","La recommandation"],a:2,e:"Art. 288 TFUE ; recommandations et avis ne lient pas.",x:"Une décision peut aussi ne désigner aucun destinataire ; elle est alors obligatoire de manière générale. Exemple : une décision de la Commission sanctionnant une entente entre entreprises.",u:["https://www.vie-publique.fr/fiches/20372-actes-juridiques-de-lue-quest-ce-quune-decision"],s:"Fiche 5"},
{id:"ue-57",t:"ue",q:"Lesquels de ces actes de l'Union ne sont pas contraignants ?",o:["Les règlements","Les directives","Les décisions","Les recommandations et avis"],a:3,e:"Ils n'ont pas de force obligatoire.",x:"Ils relèvent du « droit souple ». Le juge national doit toutefois prendre les recommandations en considération pour interpréter le droit (arrêt Grimaldi, 1989).",u:["https://www.vie-publique.fr/fiches/20373-actes-juridiques-de-lue-que-sont-les-avis-et-les-recommandations"],s:"Fiche 5"},
{id:"ue-58",t:"ue",q:"Quel rôle les parlements nationaux jouent-ils dans le processus législatif européen ?",o:["Ils votent les règlements","Ils contrôlent le respect du principe de subsidiarité","Ils nomment les commissaires","Ils n'ont aucun rôle"],a:1,e:"Mécanisme d'alerte précoce (« carton jaune ») depuis Lisbonne.",x:"Chaque parlement dispose de 8 semaines pour adresser un avis motivé. Si un tiers des voix attribuées aux parlements nationaux conteste le texte, la Commission doit le réexaminer (« carton jaune »).",u:["https://www.vie-publique.fr/fiches/20361-traite-de-lisbonne-le-role-des-parlements-nationaux"],s:"Fiche 5"},
{id:"ue-59",t:"ue",q:"Selon le principe de subsidiarité, l'Union intervient :",o:["Dans tous les domaines","Seulement si les objectifs ne peuvent être atteints de manière suffisante par les États","Uniquement à l'unanimité","Uniquement en matière monétaire"],a:1,e:"Art. 5 TUE, avec les principes d'attribution et de proportionnalité.",x:"La subsidiarité ne joue que dans les domaines qui ne relèvent pas de la compétence exclusive de l'Union. La proportionnalité impose que l'action n'excède pas ce qui est nécessaire.",u:["https://www.vie-publique.fr/fiches/20359-union-europeenne-principes-de-subsidiarite-et-de-proportionnalite","https://fr.wikipedia.org/wiki/Principe_de_subsidiarit%C3%A9"],s:"TUE, art. 5"},
{id:"ue-60",t:"ue",q:"Combien de signatures faut-il pour une initiative citoyenne européenne ?",o:["100 000","500 000","1 million, dans au moins 7 États","10 millions"],a:2,e:"La Commission est alors invitée à présenter une proposition.",x:"Le nombre minimal de signataires par État est proportionnel à son nombre d'eurodéputés. Les signatures doivent être recueillies en 12 mois.",u:["https://www.vie-publique.fr/questions-reponses/289160-linitiative-citoyenne-europeenne-en-six-questions","https://fr.wikipedia.org/wiki/Initiative_citoyenne_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-61",t:"ue",q:"Comment la PESC (politique étrangère et de sécurité commune) est-elle en principe décidée ?",o:["À la majorité qualifiée","À l'unanimité","Par la Commission seule","Par le Parlement européen"],a:1,e:"Unanimité au Conseil, sauf exceptions.",x:"Un État peut recourir à l'« abstention constructive » sans bloquer la décision. Les décisions ayant des implications militaires ou de défense sont exclues de la majorité qualifiée.",u:["https://www.vie-publique.fr/fiches/20395-existe-t-il-une-politique-etrangere-europeenne-la-pesc","https://www.vie-publique.fr/questions-reponses/293096-politique-etrangere-de-lue-comment-sont-prises-les-decisions"],s:"Fiche 5"},
{id:"ue-62",t:"ue",q:"Laquelle de ces compétences est exclusive à l'Union ?",o:["La santé publique","La politique commerciale commune","L'éducation","La fiscalité directe"],a:1,e:"Art. 3 TFUE : union douanière, règles de concurrence du marché intérieur, politique monétaire de la zone euro, conservation des ressources biologiques de la mer, politique commerciale commune.",x:"C'est la Commission qui négocie les accords commerciaux au nom des 27, sur mandat du Conseil (exemple : le CETA avec le Canada).",u:["https://www.vie-publique.fr/fiches/20401-quest-ce-que-la-politique-commerciale-commune-de-lue"],s:"Fiche 5"},
{id:"ue-63",t:"ue",q:"Quel article du TUE permet de suspendre certains droits d'un État membre qui viole gravement les valeurs de l'Union ?",o:["Article 2","Article 7","Article 49","Article 50"],a:1,e:"Procédure engagée contre la Pologne (2017) et la Hongrie (2018).",x:"Le constat d'une violation « grave et persistante » exige l'unanimité du Conseil européen (moins l'État concerné), ce qui rend la sanction difficile. La procédure contre la Pologne a été close en 2024.",u:["https://www.vie-publique.fr/fiches/20303-quelles-sanctions-en-cas-de-non-respect-des-valeurs-de-lunion-art-7-t"],s:"Fiche 5"},
{id:"ue-64",t:"ue",q:"Quel article du TUE énumère les valeurs de l'Union (dignité, liberté, démocratie, égalité, État de droit, droits de l'homme) ?",o:["Article 2","Article 5","Article 13","Article 50"],a:0,e:"Leur violation grave peut entraîner la procédure de l'article 7.",x:"Ces valeurs incluent aussi les droits des personnes appartenant à des minorités. Leur respect est une condition d'adhésion (art. 49 TUE).",u:["https://www.vie-publique.fr/fiches/20302-quelles-valeurs-lunion-europeenne-defend-elle"],s:"Fiche 5"},
{id:"ue-65",t:"ue",q:"Où et quand la Charte des droits fondamentaux de l'UE a-t-elle été proclamée ?",o:["À Rome en 1950","À Nice en 2000","À Lisbonne en 2007","À Strasbourg en 1979"],a:1,e:"Elle a valeur de traité depuis le 1er décembre 2009.",x:"Proclamée le 7 décembre 2000, elle a été proclamée de nouveau à Strasbourg le 12 décembre 2007, la veille de la signature du traité de Lisbonne.",u:["https://fr.wikipedia.org/wiki/Charte_des_droits_fondamentaux_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-66",t:"ue",q:"Qui assure le respect de la Charte des droits fondamentaux de l'UE ?",o:["La Cour européenne des droits de l'homme","La Cour de justice de l'Union européenne","Le Conseil de l'Europe","Le Médiateur européen"],a:1,e:"La CJUE ; la CEDH applique la Convention de 1950.",x:"La Charte s'impose aux États membres uniquement lorsqu'ils mettent en œuvre le droit de l'Union (art. 51). La Convention de 1950, elle, est appliquée par la Cour de Strasbourg.",u:["https://www.vie-publique.fr/fiches/271179-droits-de-lhomme-en-europe-charte-des-droits-fondamentaux-cedh"],s:"Fiche 5"},
// --- Budget ---
{id:"ue-67",t:"ue",q:"Quelle période couvre le cadre financier pluriannuel actuel de l'UE ?",o:["2014-2020","2021-2027","2024-2030","2028-2034"],a:1,e:"Environ 1 211 Md€ en prix courants, plus NextGenerationEU (environ 807 Md€). Le cadre 2028-2034 est en négociation.",x:"La Commission a présenté en juillet 2025 sa proposition pour le cadre 2028-2034.",u:["https://www.vie-publique.fr/questions-reponses/297386-le-cadre-financier-pluriannuel-europeen-cfp-en-sept-questions","https://fr.wikipedia.org/wiki/Budget_de_l'Union_europ%C3%A9enne"],s:"Fiche 5"},
{id:"ue-68",t:"ue",q:"Comment le cadre financier pluriannuel est-il adopté ?",o:["Par le Parlement seul","Par le Conseil à l'unanimité, après approbation du Parlement européen","Par la Commission","Par le Conseil à la majorité qualifiée"],a:1,e:"Art. 312 TFUE.",x:"Le CFP 2021-2027 a été adopté par un règlement du Conseil du 17 décembre 2020, après un blocage lié au mécanisme de conditionnalité relatif à l'État de droit.",u:["https://www.vie-publique.fr/fiches/20379-quest-ce-que-le-cadre-financier-pluriannuel-de-lunion-europeenne"],s:"Fiche 5"},
{id:"ue-69",t:"ue",q:"Quel est le nom du plan de relance européen adopté après la crise sanitaire ?",o:["Plan Juncker","NextGenerationEU","Horizon Europe","Erasmus+"],a:1,e:"Environ 807 Md€ en prix courants, financés par un emprunt commun.",x:"Son principal instrument est la facilité pour la reprise et la résilience. Les paiements doivent intervenir d'ici fin 2026 ; le remboursement de l'emprunt court jusqu'en 2058.",u:["https://www.vie-publique.fr/fiches/279587-en-quoi-consiste-le-plan-de-relance-next-generation-ue","https://fr.wikipedia.org/wiki/Plan_de_relance_europ%C3%A9en_de_2020"],s:"Fiche 5"},
{id:"ue-70",t:"ue",q:"Laquelle de ces ressources n'est pas une ressource propre de l'UE ?",o:["Les droits de douane","La ressource fondée sur la TVA","La contribution sur les emballages plastiques non recyclés","L'impôt sur le revenu des citoyens européens"],a:3,e:"Il n'existe pas d'impôt européen sur le revenu.",x:"Le plafond des ressources propres est fixé par une décision adoptée à l'unanimité et ratifiée par chaque État. Les droits de douane perçus par les États sont reversés à l'Union, déduction faite de 25 % de frais de perception.",u:["https://www.vie-publique.fr/fiches/20375-quelles-sont-les-ressources-de-lunion-europeenne"],s:"Fiche 5"},
{id:"ue-71",t:"ue",q:"Le budget annuel de l'Union européenne :",o:["Peut être voté en déficit","Doit être en équilibre","Est financé surtout par l'emprunt","Est voté par les parlements nationaux"],a:1,e:"Principe d'équilibre : pas de déficit.",x:"Le budget annuel est adopté conjointement par le Parlement et le Conseil selon une procédure spéciale (art. 314 TFUE), dans le respect du cadre financier pluriannuel.",u:["https://www.vie-publique.fr/fiches/20374-quelles-sont-les-regles-budgetaires-de-lunion-europeenne","https://www.vie-publique.fr/fiches/20377-comment-le-budget-de-lunion-europeenne-est-il-elabore-et-vote"],s:"Fiche 5"},
{id:"ue-72",t:"ue",q:"Quel État membre est le deuxième contributeur au budget de l'UE ?",o:["L'Italie","La France","L'Espagne","Les Pays-Bas"],a:1,e:"Après l'Allemagne.",x:"L'Allemagne, la France et l'Italie sont les trois premiers contributeurs bruts au budget de l'Union.",u:["https://www.vie-publique.fr/fiches/20380-comment-la-france-participe-t-elle-au-financement-de-lue"],s:"Fiche 5"},
{id:"ue-73",t:"ue",q:"Dans le budget de l'État français, comment est versée la contribution à l'UE ?",o:["Par une mission budgétaire","Par un prélèvement sur recettes","Par un compte d'affectation spéciale","Par la Sécurité sociale"],a:1,e:"Prélèvement sur recettes au profit de l'Union européenne.",x:"Ce prélèvement est évalué chaque année par un article de la première partie de la loi de finances.",u:["https://www.vie-publique.fr/fiches/20380-comment-la-france-participe-t-elle-au-financement-de-lue"],s:"Fiche 4"},
// --- Politiques ---
{id:"ue-74",t:"ue",q:"En quelle année la politique agricole commune (PAC) a-t-elle été lancée ?",o:["1957","1962","1973","1992"],a:1,e:"Elle reste, avec la cohésion, l'un des deux premiers postes du budget.",x:"Elle repose sur deux piliers : les aides directes et de marché (FEAGA) et le développement rural (Feader). La France en est la première bénéficiaire.",u:["https://www.vie-publique.fr/fiches/20381-quest-ce-que-la-politique-agricole-commune-pac","https://fr.wikipedia.org/wiki/Politique_agricole_commune"],s:"Fiche 5"},
{id:"ue-75",t:"ue",q:"Quel fonds finance principalement la politique régionale (cohésion) ?",o:["Le FEDER","Le MES","Le FEAGA","La BCE"],a:0,e:"Fonds européen de développement régional, avec le FSE+ et le Fonds de cohésion.",x:"Créé en 1975, le FEDER vise à réduire les écarts de développement entre régions. Le Fonds de cohésion ne bénéficie qu'aux États dont le RNB par habitant est inférieur à 90 % de la moyenne.",u:["https://www.vie-publique.fr/fiches/20389-politique-de-cohesion-quels-sont-les-fonds-structurels-de-lue","https://fr.wikipedia.org/wiki/Fonds_europ%C3%A9en_de_d%C3%A9veloppement_r%C3%A9gional"],s:"Fiche 5"},
{id:"ue-76",t:"ue",q:"Quel est l'objet de l'espace Schengen ?",o:["La monnaie unique","La suppression des contrôles aux frontières intérieures","Le marché unique des capitaux","La défense commune"],a:1,e:"Accords de 1985, convention de 1990 ; tous les États de l'UE n'en font pas partie (Irlande, Chypre).",x:"Il compte 29 États, dont quatre non membres de l'UE : Islande, Liechtenstein, Norvège et Suisse. Des contrôles temporaires aux frontières intérieures peuvent être rétablis en cas de menace grave.",u:["https://www.vie-publique.fr/questions-reponses/269481-lespace-schengen-en-8-questions-reponses","https://fr.wikipedia.org/wiki/Espace_Schengen"],s:"Connaissance UE"},
{id:"ue-77",t:"ue",q:"Depuis quand la Bulgarie et la Roumanie sont-elles pleinement membres de l'espace Schengen ?",o:["2007","2014","1er janvier 2025","Elles n'en sont pas membres"],a:2,e:"Frontières aériennes et maritimes en mars 2024, terrestres le 1er janvier 2025.",x:"L'espace Schengen compte désormais 29 États : 25 membres de l'UE (tous sauf Chypre et l'Irlande) et 4 États associés.",u:["https://fr.wikipedia.org/wiki/Espace_Schengen"],s:"Connaissance UE"},
{id:"ue-78",t:"ue",q:"Quel ensemble de règles encadre les budgets nationaux et a été réformé en 2024 ?",o:["Le Pacte de stabilité et de croissance","La PAC","Le traité de Prüm","Le pacte budgétaire de Lisbonne"],a:0,e:"Nouvelles règles budgétaires en vigueur depuis avril 2024, fondées sur une trajectoire de dépenses nettes.",x:"Les seuils de 3 % et 60 % sont conservés ; chaque État présente un plan budgétaire et structurel à moyen terme sur 4 ans, extensible à 7 ans en échange de réformes.",u:["https://www.vie-publique.fr/fiches/21801-quest-ce-que-le-pacte-de-stabilite-et-de-croissance-psc","https://fr.wikipedia.org/wiki/Pacte_de_stabilit%C3%A9_et_de_croissance"],s:"Connaissance UE"},
{id:"ue-79",t:"ue",q:"Comment s'appelle le cycle annuel de coordination des politiques économiques et budgétaires des États membres ?",o:["Le semestre européen","Le trilogue","La comitologie","La méthode ouverte"],a:0,e:"Mis en place en 2011.",x:"Au printemps, les États transmettent leurs programmes ; la Commission formule des recommandations par pays, adoptées par le Conseil en juillet.",u:["https://fr.wikipedia.org/wiki/Semestre_europ%C3%A9en","https://www.vie-publique.fr/fiches/21795-existe-t-il-une-gouvernance-economique-au-sein-de-lue"],s:"Connaissance UE"},
{id:"ue-80",t:"ue",q:"Quel mécanisme créé en 2012 peut accorder une aide financière aux États de la zone euro en difficulté ?",o:["Le Mécanisme européen de stabilité (MES)","Le FEDER","La BEI","Le Fonds social européen"],a:0,e:"Il a succédé aux fonds temporaires créés pendant la crise des dettes souveraines.",x:"Installé à Luxembourg, il dispose d'une capacité de prêt de 500 Md€. Il a notamment aidé Chypre et la Grèce.",u:["https://www.vie-publique.fr/fiches/280943-quest-ce-que-le-mecanisme-europeen-de-stabilite-mes","https://fr.wikipedia.org/wiki/M%C3%A9canisme_europ%C3%A9en_de_stabilit%C3%A9"],s:"Connaissance UE"},
{id:"ue-81",t:"ue",q:"Quel est l'objectif du Pacte vert pour l'Europe (2019) ?",o:["La neutralité climatique en 2050","La fin de la PAC","Un impôt carbone sur les ménages","L'interdiction du nucléaire"],a:0,e:"Loi européenne sur le climat : −55 % d'émissions en 2030 par rapport à 1990, neutralité en 2050.",x:"Le paquet « Fit for 55 » (2021) décline l'objectif de −55 %, notamment par l'extension du marché du carbone et un mécanisme d'ajustement carbone aux frontières.",u:["https://www.vie-publique.fr/eclairage/272297-pacte-vert-et-paquet-climat-lue-vise-la-neutralite-carbone-des-2050","https://fr.wikipedia.org/wiki/Pacte_vert_pour_l'Europe"],s:"Connaissance UE"},
{id:"ue-82",t:"ue",q:"Où le Socle européen des droits sociaux a-t-il été proclamé en 2017 ?",o:["À Göteborg","À Lisbonne","À Paris","À Bruxelles"],a:0,e:"Politique sociale : 20 principes (égalité des chances, conditions de travail équitables, protection sociale).",x:"Il a été proclamé conjointement par le Parlement, le Conseil et la Commission le 17 novembre 2017. Un plan d'action de 2021 fixe des objectifs pour 2030, dont un taux d'emploi de 78 %.",u:["https://www.vie-publique.fr/fiches/20406-quelles-sont-les-realisations-de-lue-en-matiere-sociale"],s:"Connaissance UE"},
{id:"ue-83",t:"ue",q:"Quel office européen lutte contre la fraude aux intérêts financiers de l'Union ?",o:["Europol","L'OLAF","Frontex","Eurostat"],a:1,e:"Office européen de lutte antifraude (1999) ; le Parquet européen poursuit pénalement depuis 2021.",x:"L'OLAF mène des enquêtes administratives et transmet ses conclusions aux autorités nationales ou au Parquet européen. Il dépend de la Commission mais est indépendant pour ses enquêtes.",u:["https://fr.wikipedia.org/wiki/Office_europ%C3%A9en_de_lutte_antifraude"],s:"Connaissance UE"},
{id:"ue-84",t:"ue",q:"Depuis quand le Parquet européen, compétent pour les fraudes au budget de l'Union, est-il opérationnel ?",o:["2009","2015","2021","2025"],a:2,e:"Juin 2021, siège à Luxembourg.",x:"La plupart des États membres y participent, dont la France. Il poursuit notamment les fraudes transfrontières à la TVA d'au moins 10 M€.",u:["https://fr.wikipedia.org/wiki/Parquet_europ%C3%A9en"],s:"Connaissance UE"},
{id:"ue-85",t:"ue",q:"Quelle agence européenne est chargée de la garde des frontières extérieures ?",o:["Europol","Frontex","Eurojust","L'EFSA"],a:1,e:"Siège à Varsovie.",x:"Créée en 2004 et devenue Agence européenne de garde-frontières et de garde-côtes en 2016, elle appuie les États, qui restent responsables du contrôle de leurs frontières.",u:["https://fr.wikipedia.org/wiki/Agence_europ%C3%A9enne_de_garde-fronti%C3%A8res_et_de_garde-c%C3%B4tes"],s:"Connaissance UE"},
{id:"ue-86",t:"ue",q:"Quel est l'hymne de l'Union européenne ?",o:["La Marseillaise","L'Ode à la joie (Beethoven)","Le Boléro (Ravel)","Le Canon (Pachelbel)"],a:1,e:"Prélude de l'« Ode à la joie », 4e mouvement de la 9e symphonie ; le drapeau compte 12 étoiles.",x:"L'hymne n'a pas de paroles officielles. Adopté par le Conseil de l'Europe en 1972, il a été repris par les Communautés en 1985.",u:["https://european-union.europa.eu/principles-countries-history/symbols/european-anthem_fr","https://fr.wikipedia.org/wiki/Hymne_europ%C3%A9en"],s:"Connaissance UE"},
{id:"ue-87",t:"ue",q:"Combien d'étoiles figurent sur le drapeau européen ?",o:["12","15","27","28"],a:0,e:"Le nombre ne dépend pas du nombre d'États : il symbolise la perfection et l'unité.",x:"Le drapeau a été adopté par le Conseil de l'Europe en 1955, puis par les Communautés européennes en 1985-1986.",u:["https://european-union.europa.eu/principles-countries-history/symbols/european-flag_fr","https://fr.wikipedia.org/wiki/Drapeau_europ%C3%A9en"],s:"Connaissance UE"},
{id:"ue-88",t:"ue",q:"En quelle année l'union douanière de la CEE a-t-elle été achevée ?",o:["1958","1968","1979","1993"],a:1,e:"1er juillet 1968 : suppression des droits de douane intérieurs et tarif extérieur commun.",x:"L'union douanière s'étend aujourd'hui à la Turquie pour les produits industriels, ainsi qu'à Andorre et à Saint-Marin.",u:["https://fr.wikipedia.org/wiki/Union_douani%C3%A8re_de_l'Union_europ%C3%A9enne"],s:"Connaissance UE"},
{id:"ue-89",t:"ue",q:"Quel programme d'échanges universitaires a été lancé en 1987 ?",o:["Erasmus","Horizon","Leonardo","Comenius"],a:0,e:"Devenu Erasmus+ en 2014.",x:"Erasmus+ couvre aussi la formation professionnelle, la jeunesse et le sport. Son nom rend hommage à l'humaniste Érasme.",u:["https://www.vie-publique.fr/fiches/20324-quest-ce-que-le-programme-erasmus","https://fr.wikipedia.org/wiki/Erasmus"],s:"Connaissance UE"},
{id:"ue-90",t:"ue",q:"Depuis quand l'Ukraine a-t-elle le statut de pays candidat à l'adhésion ?",o:["2014","Juin 2022","2024","Elle ne l'a pas"],a:1,e:"Statut accordé à l'Ukraine et à la Moldavie en juin 2022 ; négociations ouvertes en juin 2024.",x:"La demande d'adhésion a été déposée le 28 février 2022, quelques jours après l'invasion russe. La Géorgie a obtenu le statut de candidat en décembre 2023.",u:["https://www.vie-publique.fr/questions-reponses/284305-ukraine-moldavie-georgie-quelles-relations-avec-lunion-europeenne"],s:"Connaissance UE"},
{id:"ue-91",t:"ue",q:"Quelle clause du TUE, invoquée par la France après les attentats de novembre 2015, prévoit l'assistance mutuelle en cas d'agression armée ?",o:["Article 42 paragraphe 7","Article 50","Article 7","Article 222 TFUE"],a:0,e:"Clause d'assistance mutuelle ; l'art. 222 TFUE est la clause de solidarité (catastrophe, terrorisme).",x:"Activée pour la première fois par la France le 17 novembre 2015, elle oblige les États à apporter « aide et assistance par tous les moyens en leur pouvoir », sans préjudice des engagements pris dans l'OTAN.",u:["https://www.vie-publique.fr/questions-reponses/297150-quest-ce-que-la-clause-de-defense-mutuelle-de-lunion-europeenne"],s:"Connaissance UE"},
{id:"ue-92",t:"ue",q:"Quelle directive transposée en France fixe l'imposition minimale de 15 % des grands groupes ?",o:["La directive Pilier 2","La directive TVA","La directive DAC 6","La directive mère-fille"],a:0,e:"Seuil : chiffre d'affaires consolidé d'au moins 750 M€, application depuis 2024.",x:"La France l'a transposée par la loi de finances pour 2024. Les règles reposent sur l'accord conclu en 2021 au sein du Cadre inclusif OCDE/G20.",u:["https://fr.wikipedia.org/wiki/Taux_d'imposition_mondial_minimum"],s:"Fiche 5"},
{id:"ue-93",t:"ue",q:"Quel règlement européen de 2024 encadre l'intelligence artificielle selon le niveau de risque ?",o:["Le RGPD","L'AI Act (règlement sur l'IA)","Le DMA","Le DSA"],a:1,e:"Premier cadre juridique général sur l'IA au monde.",x:"Le règlement (UE) 2024/1689 interdit par exemple la notation sociale et impose des obligations de transparence pour les contenus générés par l'IA.",u:["https://www.vie-publique.fr/questions-reponses/292157-ai-act-le-reglement-europeen-sur-lintelligence-artificielle-ia","https://fr.wikipedia.org/wiki/R%C3%A8glement_sur_l'intelligence_artificielle"],s:"Fiche 6"},
{id:"ue-94",t:"ue",q:"Quel règlement européen impose des obligations aux très grandes plateformes en matière de contenus illicites ?",o:["Le Digital Services Act (DSA)","Le RGPD","L'AI Act","Le code des douanes de l'Union"],a:0,e:"Le DSA régule les contenus ; le DMA (Digital Markets Act) vise les pratiques des « contrôleurs d'accès ».",x:"Le DSA s'applique à toutes les plateformes depuis le 17 février 2024 ; les très grandes plateformes (plus de 45 millions d'utilisateurs dans l'UE) sont supervisées directement par la Commission.",u:["https://www.vie-publique.fr/eclairage/285115-dsa-le-reglement-sur-les-services-numeriques-ou-digital-services-act","https://fr.wikipedia.org/wiki/R%C3%A8glement_sur_les_services_num%C3%A9riques"],s:"Connaissance UE"},
{id:"ue-95",t:"ue",q:"Quelle est la minorité de blocage au Conseil de l'UE en majorité qualifiée ?",o:["Au moins 4 États représentant plus de 35 % de la population","Un seul État, quel qu'il soit","Au moins 10 États, quelle que soit leur population","Au moins 2 États représentant 50 % de la population"],a:0,e:"Corollaire de la double majorité 55 % des États / 65 % de la population.",x:"La règle des 4 États empêche les trois États les plus peuplés de bloquer seuls une décision. Hors proposition de la Commission, la majorité qualifiée exige 72 % des États.",u:["https://www.vie-publique.fr/fiches/20348-le-vote-la-majorite-qualifiee-au-sein-du-conseil-de-lue"],s:"Fiche 5"}
);
